package com.mytransitgps.modules.ciq;
import static org.junit.jupiter.api.Assertions.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.mytransitgps.modules.ciq.client.LtaTrafficSpeedClient;import com.mytransitgps.modules.ciq.collector.CiqTrafficSpeedCollector;import com.mytransitgps.modules.ciq.config.CiqProperties;import com.mytransitgps.modules.ciq.storage.CiqJsonStorageService;import com.mytransitgps.persistence.config.MyTransitGpsDatabaseProperties;import com.mytransitgps.persistence.service.WorkspaceRootResolver;import com.mytransitgps.platform.collection.*;import com.mytransitgps.platform.http.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.Instant;import java.util.Map;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class Api01NodeTraceTest {@TempDir Path tmp;@Test void rawChainRunsThroughHttpStorageParserQc()throws Exception{Files.createDirectories(tmp.resolve("BusGPS"));Files.createDirectories(tmp.resolve("CIQ"));Files.createDirectories(tmp.resolve("logs"));var dp=new MyTransitGpsDatabaseProperties();dp.setWorkspaceRoot(tmp.toString());var p=new CiqProperties();p.setEnabled(true);p.getLta().setBaseUrl("https://example.test/lta");p.getLta().setAccountKey("test");p.getCollectors().getTrafficSpeed().setEnabled(true);p.getCollectors().getTrafficSpeed().setEndpoint("/TrafficSpeedBands");p.getCollectors().getTrafficSpeed().setPageSize(500);p.getStorage().setRootDirectory("CIQ");p.getPersistence().setDatabaseWriteEnabled(false);TrafficHttpClient h=(u,hd,c,r)->{var now=Instant.parse("2026-08-30T09:00:00Z");var b="{\"value\":[{\"LinkID\":\"1\",\"RoadName\":\"BKE\",\"RoadCategory\":\"1\",\"SpeedBand\":4,\"MinimumSpeed\":\"30\",\"MaximumSpeed\":\"39\",\"StartLon\":\"103.7\",\"StartLat\":\"1.4\",\"EndLon\":\"103.8\",\"EndLat\":\"1.5\"}]}".getBytes(StandardCharsets.UTF_8);return new HttpRequestResult(u,u,200,b,Map.of(),now,now,1,null,null);};var c=new CiqTrafficSpeedCollector(new LtaTrafficSpeedClient(h,p),p,new CiqJsonStorageService(new WorkspaceRootResolver(dp),p),new ObjectMapper());var ctx=CollectionContext.scheduled(ModuleCode.CIQ,CollectorCode.CIQ_TRAFFIC_SPEED,Instant.now());var result=c.collect(ctx);assertEquals(1,result.receivedCount());assertTrue(Files.walk(tmp.resolve("CIQ")).anyMatch(x->x.toString().endsWith(".json")));}}
